public class RabinKarp {
   private const int R = 256;
   private const int Q = 101;

   private static int Search(string pat, string txt) {
      int M = pat.Length;
      int N = txt.Length;
      long patHash = Hash(pat, M);

      for (int i = 0; i <= N - M; i++) {
         long txtHash = Hash(txt.Substring(i, M), M);
         if (patHash == txtHash)
            return i; // ocorrência? colisão?
      }
      return N; // nenhuma ocorrência
   }

   private static long Hash(string s, int M) {
      long h = 0;
      for (int j = 0; j < M; j++)
         h = (h * R + s[j]) % Q;
      return h;
   }

   public static void Main() {
      int result = Search("", "");
      Console.WriteLine(result < "".Length ? $"Found at index {result}" : "No occurrence found");
   }
}
